"""Partition Equal Subset Sum — 0/1 subset-sum over a bitset.

Each number shifts the set of reachable sums; bit `target` tells whether half the
total is achievable.

Time: O(n * sum / 64)   Space: O(sum)
"""
from typing import List


class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        reachable = 1                      # bit i set == sum i is reachable
        for value in nums:
            reachable |= reachable << value
        return bool(reachable >> target & 1)
